import itertools,json,numpy as np
E=np.array([[1.,0.],[0.,1.],[-1.,-1.]])
C=np.zeros((2,2,2)); C[0,0,0]=1; C[1,0,1]=1; C[1,1,0]=1; C[:,1,1]=[-1,-1]
bs=[]
for subset in json.load(open('kaggle_tasks_data/task007.json')).values():
 for ex in subset:
  b=[0,0,0]
  for i,row in enumerate(ex['input']):
   for j,x in enumerate(row):b[(i+j)%3]+=x==0
  bs.append(b)
bs=np.unique(bs,axis=0)
mats=[]
for z in itertools.product(range(-2,3),repeat=4):
 A=np.array(z,dtype=float).reshape(2,2)
 if abs(np.linalg.det(A))>.1:mats.append((z,A))
print('start',len(mats),flush=True)
for pi,(pz,P) in enumerate(mats):
 Q=np.linalg.inv(P);F=E@Q.T
 for lz,L in mats:
  U=E@L.T; M=np.einsum('qk,kij,ia,jb->abq',L,C,P,P)
  for perm in ((2,0,1),(2,1,0),(0,2,1),(1,2,0)):
   T=np.transpose(M,perm); V=np.einsum('su,sv,uvq->sq',F,F,T); K=V@U.T
   off=K.copy();np.fill_diagonal(off,0)
   if np.all(np.diag(K)>1e-9) and np.all(off<=1e-9) and np.all(bs@K.T<=1e-9):
    print('FOUND',pz,lz,perm,'K',K,'F',F,'M',M,flush=True);raise SystemExit
print('none',flush=True)
