/bin/bash -lc "~/.venv/bin/python - <<'PY'
import numpy as np
th=2*np.pi*np.arange(3)/3;F=np.stack([np.cos(th),np.sin(th)],1)
rows=[];target=[]
for i in range(3):
 for j in range(3):
  for r in range(3):
   for c in range(3):
    rows.append(np.outer(F[i]*F[r],F[j]*F[c]).ravel())
    target.append(np.cos(th[(i+j-r-c)%3]))
A=np.array(rows);y=np.array(target);m=np.linalg.lstsq(A,y,rcond=None)[0]
print(m.reshape(2,2),np.max(np.abs(A@m-y)),np.linalg.matrix_rank(A))
# optimize F and M sign margins
from scipy.optimize import differential_evolution
pairs=[(i,j) for i in range(3) for j in range(3)];Y=np.array([[1 if (i+j-r-c)%3==0 else -1 for r,c in pairs] for i,j in pairs])
def obj(x):
 f=x[:6].reshape(3,2);M=x[6:].reshape(2,2);K=np.empty((9,9))
 for p,(i,j) in enumerate(pairs):
  for z,(r,c) in enumerate(pairs):K[p,z]=(f[i]*f[r])@M@(f[j]*f[c])
 scale=np.max(np.abs(K))+1e-12
 return -np.min(Y*K/scale)
res=differential_evolution(obj,[(-2,2)]*10,seed=3,maxiter=150,popsize=8,tol=1e-6,polish=True)
print('margin',-res.fun,'F',res.x[:6].reshape(3,2),'M',res.x[6:].reshape(2,2))
PY"

